SOURCE_POSITIONS=frozenset(p for a,z in SPANS for p in range(a,z))
BODIES=rle.BODIES
sha,dump,keys,same,uint,exact_list=rle.sha,rle.dump,rle.keys,rle.same,rle.uint,rle.exact_list
